function table(list){return list.length?'<div class="dept2-table-wrap"><table class="dept2-table"><thead><tr><th>عنوان / شناسه</th>'+mod.fields.slice(0,4).map(f=>'<th>'+f[1]+'</th>').join("")+'<th>وضعیت</th><th>عملیات</th></tr></thead><tbody>'+list.map(r=>'<tr><td><b>'+esc(r.title||r.subject||r.orderNo||r.plate||r.assetCode||r.letterNo||"پرونده")+'</b><small>'+esc(r.description||"")+'</small></td>'+mod.fields.slice(0,4).map(f=>'<td>'+esc(r[f[0]]||"—")+'</td>').join("")+'<td><span class="dept2-status">'+esc(r.status||"ثبت‌شده")+'</span></td><td><div class="dept2-row-actions"><button class="dept2-btn small" data-view="'+esc(r.id)+'">پیش‌نمایش</button><button class="dept2-btn small" data-edit="'+esc(r.id)+'">ویرایش</button><button class="dept2-btn small danger" data-delete="'+esc(r.id)+'">حذف</button></div></td></tr>').join("")+'</tbody></table></div>':'<div class="dept2-empty">برای این بانک هنوز پرونده‌ای ثبت نشده است. از گزینه «ثبت جدید» برای ایجاد نخستین پرونده استفاده کنید.</div>'}
