function form(record={}){content.innerHTML='<div class="dept2-form-card"><div class="dept2-section-head"><div><h2>'+(record.id?"ویرایش پرونده":"ثبت پرونده جدید")+'</h2><p>اطلاعات را ثبت کنید؛ پس از ذخیره، پرونده در بانک قابل مشاهده و پیش‌نمایش خواهد بود.</p></div></div><form class="dept2-form" id="d1-form">'+mod.fields.map(f=>fieldHtml(f,record)).join("")+'<label class="wide">عنوان / نام پرونده (در صورت نیاز)<input name="title" value="'+esc(record.title||"")+'" placeholder="عنوان قابل جست‌وجوی پرونده"></label><div class="wide dept2-form-actions"><button class="dept2-btn primary" type="submit">ذخیره پرونده</button><a class="dept2-btn" href="'+href(mod.id)+'">انصراف</a></div></form></div>';$("#d1-form").onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)),next=read(mod.id);if(mod.id==="vehicle-usage"){const start=Number(d.startKm)||0,end=Number(d.endKm)||0;if(end<start){alert("کیلومتر پایان نمی‌تواند از کیلومتر شروع کمتر باشد.");return}d.distance=end-start;}if(mod.id==="vehicle-depreciation"){const settings=read("vehicle-settings").filter(x=>x.status==="فعال").slice(-1)[0]||{},cost=Number(d.purchaseCost)||0,residual=Number(d.residualValue)||0,life=Number(d.usefulLife)||Number(settings.usefulLife)||0,method=d.method;const jalaliSerial=value=>{const digits=String(value||"").replace(/[۰-۹]/g,ch=>"۰۱۲۳۴۵۶۷۸۹".indexOf(ch)).replace(/[٠-٩]/g,ch=>"٠١٢٣٤٥٦٧٨٩".indexOf(ch));const m=digits.match(/(\d{4})[/-](\d{1,2})[/-](\d{1,2})/);return m?Number(m[1])*365.2425+(Number(m[2])-1)*30.4367+Number(m[3]):null};const nowParts=new Intl.DateTimeFormat("en-US-u-ca-persian-nu-latn",{year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date()),todayJ=[nowParts.find(x=>x.type==="year")?.value,nowParts.find(x=>x.type==="month")?.value,nowParts.find(x=>x.type==="day")?.value].join("/");let value=null;if(method==="خط مستقیم"&&cost>0&&life>0){const start=jalaliSerial(d.purchaseDate),end=jalaliSerial(d.valuationDate||todayJ);if(start!==null&&end!==null){const years=Math.max(0,(end-start)/365.2425),annual=Math.max(0,(cost-residual)/life);d.annualDepreciation=String(Math.round(annual));value=Math.max(residual,cost-annual*years)}}else if(method==="کارکردمحور"&&cost>0&&Number(d.usefulKm)>0){const v=read("vehicles").find(x=>String(x.plate||"")===String(d.plate||"")||String(x.vehicleCode||"")===String(d.plate||""));if(v){const fraction=Math.max(0,((Number(v.odometer)||0)-(Number(d.purchaseOdometer)||0))/Number(d.usefulKm));value=Math.max(residual,cost-(cost-residual)*Math.min(1,fraction))}}else if(method==="کارشناسی"&&cost>0&&(Number(d.factor)||Number(settings.depreciationFactor))>0){const rawFactor=Number(d.factor)||Number(settings.depreciationFactor),factor=rawFactor>1?rawFactor/100:rawFactor;value=Math.max(residual,Math.min(cost,cost*factor))}if(value!==null)d.bookValue=String(Math.round(value))}if(mod.id==="vehicles"){const plate=String(d.plate||"").trim(),vin=String(d.vin||"").trim();if(plate&&next.some(x=>x.id!==record.id&&String(x.plate||"").trim()===plate)){alert("این شماره پلاک قبلاً در بانک ناوگان ثبت شده است.");return}if(vin&&next.some(x=>x.id!==record.id&&String(x.vin||"").trim()===vin)){alert("این شماره شاسی قبلاً ثبت شده است.");return}if(!record.id&&!d.vehicleCode){const prefix=d.vehicleType==="موتورسیکلت"?"MOT":"CAR",nums=next.map(x=>String(x.vehicleCode||"")).filter(x=>x.startsWith(prefix+"-")).map(x=>Number(x.slice(4))||0),n=Math.max(0,...nums)+1;d.vehicleCode=prefix+"-"+String(n).padStart(4,"0")}}const row={...record,...d,id:record.id||"d1-"+Date.now().toString(36),createdAt:record.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(record.id){const i=next.findIndex(x=>x.id===record.id);if(i>=0)next[i]=row}else next.unshift(row);if(write(mod.id,next)){
 if(mod.id==="vehicles"&&!record.id){
  const defaults=[["بیمه شخص ثالث","مدارک قانونی",365,0],["معاینه فنی","مدارک قانونی",365,0],["سرویس دوره‌ای کامل","نگهداری",180,10000],["تعویض روغن و فیلترها","نگهداری",90,5000],["بازدید و وضعیت لاستیک‌ها","ایمنی",180,12000],["کپسول آتش‌نشانی و تجهیزات ایمنی","ایمنی",365,0]].map((x,i)=>({id:"d1-check-"+Date.now().toString(36)+"-"+i,vehicleCode:row.vehicleCode,plate:row.plate,checkType:x[0],group:x[1],intervalDays:x[2],intervalKm:x[3],dueOdometer:x[3]?(Number(row.odometer)||0)+x[3]:0,result:"بررسی‌نشده",status:"بررسی‌نشده",description:"برای آغاز پایش، بررسی اولیه و تاریخ/کیلومتر سررسید را ثبت کنید."}));
  write("vehicle-checklist",[...defaults,...read("vehicle-checklist")]);
 }
 if(["vehicle-fuel","vehicle-maintenance","vehicle-usage","vehicle-handover"].includes(mod.id)){
  const vehicles=read("vehicles"),v=vehicles.find(x=>(row.vehicleCode&&x.vehicleCode===row.vehicleCode)||(row.plate&&x.plate===row.plate));
  if(v){const km=mod.id==="vehicle-usage"?Number(row.endKm)||0:Number(row.odometer)||0;if(km>Number(v.odometer||0))v.odometer=km;if(mod.id==="vehicle-handover"&&["تأییدشده","تحویل انجام شد"].includes(row.status)){if(row.toUnit)v.unit=row.toUnit;if(row.toPersonCode)v.driverCode=row.toPersonCode}write("vehicles",vehicles)}
 }
 
 if(mod.id==="vehicle-documents"){
  const checks=read("vehicle-checklist"),type=row.documentType||"",match=type.includes("بیمه")?"بیمه شخص ثالث":type==="معاینه فنی"?"معاینه فنی":"";
  if(match&&row.expiryDate){checks.forEach(x=>{if((row.vehicleCode&&x.vehicleCode===row.vehicleCode)||(row.plate&&x.plate===row.plate)){if(x.checkType===match){x.dueDate=row.expiryDate;x.lastCheck=row.issueDate||new Intl.DateTimeFormat("fa-IR-u-ca-persian",{year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());x.checkedAt=x.lastCheck;x.result="معتبر";x.status="معتبر"}}});write("vehicle-checklist",checks)}
 }
 detail(row)
}}}
function fleetRelated(r){
 const vehicleCode=String(r.vehicleCode||r.code||"").trim(),plate=String(r.plate||"").trim();
 const ids=["vehicles","vehicle-requests","vehicle-handover","vehicle-checklist","vehicle-documents","vehicle-maintenance","vehicle-fuel","vehicle-usage","vehicle-incidents","vehicle-costs","vehicle-depreciation"];
 const matches=x=>(vehicleCode&&String(x.vehicleCode||x.code||"").trim()===vehicleCode)||(plate&&String(x.plate||"").trim()===plate)||(plate&&String(x.vehicleCode||"").trim()===plate);
 const related=ids.filter(id=>id!==mod.id).map(id=>{const m=modules.find(x=>x.id===id),items=read(id).filter(matches);return {id,title:m?.title||id,items}}).filter(x=>x.items.length);
 const events=related.flatMap(g=>g.items.map(x=>({group:g,record:x,date:x.date||x.issueDate||x.lastCheck||x.purchaseDate||"",title:x.title||x.subject||x.documentType||x.checkType||x.workType||x.costType||x.incidentType||x.operation||x.purpose||g.title,detail:x.description||x.problem||x.action||x.followup||x.notes||"",status:x.status||x.result||"ثبت‌شده"}))).sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,16);
 const heading='<div class="dept2-section-head"><div><h2>پرونده جامع و تاریخچه وسیله</h2><p>سوابق مرتبط با '+esc(plate||vehicleCode||"شناسه ثبت‌شده")+' در بانک‌های عملیاتی ناوگان</p></div></div>';
 const counts=related.length?'<div class="dept2-stat-grid">'+related.map(x=>'<a class="dept2-stat" href="'+href(x.id)+'"><span>'+esc(x.title)+'</span><b>'+fa(x.items.length)+'</b><small>مشاهده سوابق ←</small></a>').join("")+'</div>':'<div class="dept2-empty">برای این وسیله هنوز سابقه‌ای در بانک‌های عملیاتی دیگر ثبت نشده است.</div>';
 const timeline=events.length?'<div class="d1-fleet-timeline">'+events.map(e=>'<article class="d1-fleet-event"><div><b>'+esc(e.title)+'</b><small>'+esc(e.group.title)+' · '+esc(e.date||"بدون تاریخ")+'</small></div><span class="dept2-status">'+esc(e.status)+'</span><p>'+esc(e.detail||"برای مشاهده جزئیات، بانک مربوط را باز کنید.")+'</p><a href="'+href(e.group.id)+'">ورود به سابقه ←</a></article>').join("")+'</div>':'';
 return '<section class="dept2-panel d1-fleet-dossier" style="margin-top:14px">'+heading+counts+timeline+'</section>';
}
